const { execFileSync } = require('child_process');
const fs = require('fs');
const EXE = '/workspace/dataset/test13_executable';
const OUT = '/workspace/probes/string.jsonl';

const DRAFTS = [
  "http://json-schema.org/draft-03/schema#",
  "http://json-schema.org/draft-04/schema#",
  "http://json-schema.org/draft-06/schema#",
  "http://json-schema.org/draft-07/schema#",
  "https://json-schema.org/draft/2019-09/schema",
  "https://json-schema.org/draft/2020-12/schema",
];

const vectors = []; // [aObj, bObj]
const add = (a,b) => vectors.push([JSON.stringify(a), JSON.stringify(b)]);
const sweep = (a, bcore) => { add(a, bcore); for (const d of DRAFTS) add(a, Object.assign({$schema:d}, bcore)); };

const EMOJI = "\u{1F600}";        // non-BMP, 1 codepoint / 2 UTF-16 units
const FAM   = "\u{1F469}‍\u{1F469}‍\u{1F467}"; // family ZWJ seq
const FLAG  = "\u{1F1FA}\u{1F1F8}"; // regional indicators
const PRECOMP = "é";          // é precomposed (1 cp)
const DECOMP  = "é";         // é decomposed (2 cp)
const DEVA    = "क्ष"; // क्ष 3 cp
const HANGUL  = "가";          // 1 cp
const SURR_HI = "\uD83D";          // lone-ish handled via emoji only

// ---------- minLength / maxLength : ASCII ----------
sweep("abc", {minLength:5});
sweep("abc", {maxLength:2});
sweep("abc", {minLength:5, maxLength:2});
sweep("abc", {minLength:1, maxLength:5});
sweep("", {minLength:1});
sweep("", {maxLength:0});
sweep("", {minLength:0});
add("abc", {minLength:3});
add("abc", {maxLength:3});
add("abc", {minLength:4});
add("abc", {maxLength:2});
add("abc", {minLength:0});
add("abc", {maxLength:0});
add("", {minLength:1, maxLength:0});
add("abc", {minLength:2.0});
add("abc", {minLength:3.0});
add("abc", {minLength:3.5});
add("abc", {maxLength:2.5});
add("abc", {minLength:-1});
add("abc", {maxLength:-1});
add("abc", {minLength:true});
add("abc", {minLength:false});
add("abc", {maxLength:true});
add("abc", {minLength:1e2});
add("abc", {minLength:"5"});      // crash
add("abc", {maxLength:"1"});      // crash
add("abc", {minLength:null});     // crash?
add("abc", {minLength:[5]});      // crash?

// ---------- non-BMP / unicode length ----------
sweep(EMOJI, {maxLength:1});
sweep(EMOJI, {minLength:2});
add(EMOJI, {minLength:1});
add(EMOJI, {maxLength:0});
add(EMOJI+EMOJI, {maxLength:2});
add(EMOJI+EMOJI, {maxLength:1});
add(EMOJI+EMOJI, {minLength:3});
add("a"+EMOJI+"b", {maxLength:3});
add("a"+EMOJI+"b", {maxLength:2});
add("a"+EMOJI+"b", {minLength:4});
sweep(FAM, {maxLength:5});
add(FAM, {maxLength:4});
add(FAM, {minLength:5});
add(FAM, {minLength:6});
sweep(FLAG, {maxLength:2});
add(FLAG, {maxLength:1});
add(FLAG, {minLength:2});
sweep(PRECOMP, {maxLength:1});
sweep(DECOMP, {maxLength:1});
add(DECOMP, {minLength:2});
add(PRECOMP, {minLength:2});
add(DEVA, {maxLength:3});
add(DEVA, {maxLength:2});
add(DEVA, {minLength:3});
add(HANGUL, {maxLength:1});
add("Å", {maxLength:1});   // A + ring
add("Å", {maxLength:1});          // precomposed Å
add("�", {maxLength:1});
add("�abc", {minLength:4});
add("\t\n ", {minLength:3});
add("日本語", {maxLength:3});
add("日本語", {maxLength:2});
add(EMOJI, {minLength:2, maxLength:0});

// ---------- pattern : search vs fullmatch, anchors ----------
sweep("abc", {pattern:"b"});
sweep("abc", {pattern:"^b"});
sweep("abc", {pattern:"^abc$"});
sweep("abc", {pattern:"^z$"});
add("abc", {pattern:"c$"});
add("abc", {pattern:"^a"});
add("abc", {pattern:"abc"});
add("abcd", {pattern:"^abc$"});
add("xabc", {pattern:"^abc"});
add("abc", {pattern:""});
add("", {pattern:""});
add("", {pattern:"^$"});
add("", {pattern:"a"});
add("abc\n", {pattern:"^abc$"});      // Python $ matches before trailing \n
add("abc\n", {pattern:"\\Aabc\\Z"});
add("abc", {pattern:"\\Aabc\\Z"});
add("abc\n", {pattern:"abc\\Z"});
add("a\nb", {pattern:"^b$"});          // no MULTILINE by default
add("a\nb", {pattern:"(?m)^b$"});
add("a\nb", {pattern:"a.b"});          // no DOTALL
add("a\nb", {pattern:"(?s)a.b"});
add("abc\ndef", {pattern:"^def"});
add("abc\ndef", {pattern:"(?m)^def"});

// ---------- Python-specific regex syntax ----------
add("john", {pattern:"(?P<name>jo)hn"});
add("jojo", {pattern:"(?P<x>jo)(?P=x)"});
add("abc", {pattern:"(?#comment)abc"});
add("ABC", {pattern:"(?i)abc"});
add("ABC", {pattern:"(?i:abc)"});
add("ABC", {pattern:"abc"});
add("a b", {pattern:"(?x) a \\  b"});
add("foobar", {pattern:"foo(?=bar)"});
add("foobaz", {pattern:"foo(?=bar)"});
add("foobar", {pattern:"(?<=foo)bar"});
add("bazbar", {pattern:"(?<=foo)bar"});
add("foobar", {pattern:"foo(?!baz)"});
add("abc", {pattern:"(?<!x)abc"});
add("abc", {pattern:"a(?:b)c"});
add("aaa", {pattern:"^a{2}$"});
add("aa", {pattern:"^a{2}$"});
add("aaa", {pattern:"a{2}"});
add("abc", {pattern:"[[:alpha:]]+"});   // POSIX class -> python treats as set, may error
add("abc", {pattern:"\\p{L}+"});        // unicode property: python error?
add("abc", {pattern:"(?P<n>a)(?(n)bc)"});

// ---------- \d \w \s \b unicode semantics ----------
add("١٢٣", {pattern:"^\\d+$"});          // Arabic-Indic digits
add("١٢٣", {pattern:"^[0-9]+$"});
add("١٢٣", {pattern:"^\\w+$"});
add("१२३", {pattern:"^\\d+$"});          // Devanagari digits
add("123", {pattern:"^\\d+$"});
add("café", {pattern:"^\\w+$"});
add("café", {pattern:"^[a-z]+$"});
add("日本語", {pattern:"^\\w+$"});
add("Ünïcödé", {pattern:"^\\w+$"});
add("a b", {pattern:"^a\\sb$"});     // NBSP is \s in Python unicode
add("a b", {pattern:"^a\\sb$"});
add("a b", {pattern:"a\\sb"});        // EM SPACE
add("café", {pattern:"\\bcafé\\b"});
add("xabcx", {pattern:"\\babc\\b"});
add("x abc x", {pattern:"\\babc\\b"});
add("naïve", {pattern:"^\\w+$"});
add("_a1", {pattern:"^\\w+$"});
add("a-b", {pattern:"^\\w+$"});
add("١٢٣", {pattern:"^\\D+$"});
add("abc", {pattern:"^\\W+$"});
add(EMOJI, {pattern:"^.$"});               // 1 codepoint in Python
add(EMOJI, {pattern:"^..$"});
add(EMOJI, {pattern:"^\\w$"});
add(EMOJI, {pattern:"^\\W$"});
add(EMOJI+EMOJI, {pattern:"^..$"});
add(DECOMP, {pattern:"^.$"});
add(PRECOMP, {pattern:"^.$"});

// ---------- invalid / non-string patterns (crash) ----------
add("abc", {pattern:"["});
add("abc", {pattern:"(unclosed"});
add("abc", {pattern:")"});
add("abc", {pattern:"a{2,1}"});
add("abc", {pattern:"*"});
add("abc", {pattern:"a**"});
add("abc", {pattern:"\\"});
add("abc", {pattern:"(?P<1bad>a)"});
add("abc", {pattern:"(?<name>a)"});        // .NET style, invalid in Python
add("abc", {pattern:"a|*"});
add("abc", {pattern:123});
add("abc", {pattern:null});
add("abc", {pattern:["a"]});
add(5,     {pattern:"["});                  // non-string instance: still crash?
add(5,     {pattern:123});

// ---------- pattern applied to non-strings ----------
sweep(5, {pattern:"^z$"});
add(null, {pattern:"^z$"});
add(true, {pattern:"^true$"});
add([], {pattern:"^z$"});
add({}, {pattern:"^z$"});
add(5, {minLength:5});
add(null, {minLength:5});
add(true, {minLength:5});
add([], {minLength:5, maxLength:0});
add({"a":1}, {minLength:5});
add(5.5, {maxLength:1});

// ---------- format ----------
for (const f of ["email","idn-email","date-time","date","time","duration","ipv4","ipv6","uuid","uri","uri-reference","iri","hostname","idn-hostname","json-pointer","relative-json-pointer","regex"]) {
  add("!!!definitely-not-valid!!!", {format:f});
}
sweep("nope", {format:"email"});
sweep("nope", {format:"date-time"});
sweep("999.999.999.999", {format:"ipv4"});
sweep("zzz", {format:"uuid"});
sweep("[", {format:"regex"});
add("a@b.com", {format:"email"});
add(123, {format:"email"});
add("nope", {format:"email", minLength:10});
add("nope", {format:123});
add("nope", {format:"totally-unknown-format"});
add("nope", {$schema:"https://json-schema.org/draft/2020-12/schema", format:"email", "$vocabulary":{"https://json-schema.org/draft/2020-12/vocab/format-assertion":true}});

// ---------- content* ----------
sweep("!!!not-base64!!!", {contentEncoding:"base64"});
sweep("notjson", {contentMediaType:"application/json"});
add("YWJj", {contentEncoding:"base64"});
add("notjson", {contentMediaType:"application/json", contentSchema:{type:"object"}});
add("{\"a\":1}", {contentMediaType:"application/json", contentSchema:{type:"array"}});
add("{\"a\":1}", {contentMediaType:"application/json", contentSchema:false});
add("abc", {contentEncoding:"base64", contentMediaType:"application/json", contentSchema:{type:"array"}, minLength:10});
add("abc", {contentEncoding:12345});
add("abc", {contentSchema:{minLength:10}});
add("abc", {$schema:"http://json-schema.org/draft-07/schema#", contentEncoding:"base64", contentMediaType:"application/json"});

// ---------- combinations / error counting ----------
add("abc", {type:"string", minLength:5, maxLength:2, pattern:"^z$"});
add("abc", {type:"number", minLength:5, maxLength:2, pattern:"^z$"});
add("abc", {minLength:5, maxLength:2, pattern:"^z$", format:"email", contentEncoding:"base64"});
add({a:"x",b:"y"}, {properties:{a:{minLength:5},b:{minLength:5}}});
add({a:"x"}, {properties:{a:{minLength:5,maxLength:0,pattern:"^z$"}}});
add(["x","y"], {items:{minLength:5}});
add(["x","y","z"], {items:{minLength:5,pattern:"^q$"}});
add("x", {anyOf:[{minLength:5},{pattern:"^z$"}]});
add("x", {oneOf:[{minLength:5},{pattern:"^z$"}]});
add("x", {oneOf:[{minLength:0},{pattern:"^x$"}]});
add("x", {not:{minLength:1}});
add("x", {allOf:[{minLength:5},{maxLength:0}]});
add("x", {allOf:[{minLength:5,maxLength:0},{pattern:"^z$"}]});
add("x", {if:{minLength:1},then:{minLength:5}});
add("x", {if:{minLength:5},then:{minLength:5},else:{maxLength:0}});
add({a:"x"}, {patternProperties:{"^a$":{minLength:5}}});
add({a:"x"}, {patternProperties:{"[":{minLength:5}}});
add("x", {$ref:"#/$defs/s", $defs:{s:{minLength:5,maxLength:0}}});
add("x", true);
add("x", false);
add("x", {minLength:5, "unknownKeyword":"ignored"});

// draft3-specific
add("abc", {$schema:"http://json-schema.org/draft-03/schema#", minLength:5, pattern:"^z$"});
add("abc", {$schema:"http://json-schema.org/draft-03/schema#", type:"string", minLength:5});
add("abc", {$schema:"http://json-schema.org/draft-03/schema#", pattern:"b"});

const lines = [];
for (const [a,b] of vectors) {
  let out='', code=0;
  try {
    out = execFileSync(EXE, ['--a', a, '--b', b], {encoding:'utf8', stdio:['ignore','pipe','ignore']});
  } catch (e) {
    out = (e.stdout||'').toString();
    code = (typeof e.status === 'number') ? e.status : 1;
  }
  lines.push(JSON.stringify({a, b, out, exit: code}));
}
fs.writeFileSync(OUT, lines.join('\n')+'\n');
console.log('wrote', lines.length, 'vectors to', OUT);
