const { execFileSync } = require('child_process');
const fs = require('fs');
const EXE = '/workspace/dataset/test13_executable';
const OUT = '/workspace/probes/string.jsonl';

const vectors = [];
const add = (a, b) => vectors.push([JSON.stringify(a), JSON.stringify(b)]);

// lazy compile: invalid pattern in an unreached branch
add({ x: 1 }, { properties: { y: { pattern: "[" } } });
add({ y: 5 }, { properties: { y: { pattern: "[" } } });
add({ y: "s" }, { properties: { y: { pattern: "[" } } });
add(5, { anyOf: [{ pattern: "[" }, { type: "integer" }] });
add("s", { anyOf: [{ type: "integer" }, { pattern: "[" }] });
add("s", { not: { pattern: "[" } });
add("s", { if: { pattern: "[" }, then: {} });

// python-only regex extras
add("aa", { pattern: "^(a)\\1$" });
add("ab", { pattern: "^(a)\\1$" });
add("aaa", { pattern: "^(?>a*)a$" });          // atomic group (3.11+)
add("aaa", { pattern: "^a*+a$" });             // possessive (3.11+)
add("A", { pattern: "\\N{LATIN CAPITAL LETTER A}" });
add("", { pattern: "^\\a$" });
add("a", { pattern: "^\\141$" });              // octal escape
add("a", { pattern: "^\\x61$" });
add("a", { pattern: "^\\u0061$" });
add("\u{1F600}", { pattern: "^\\U0001F600$" });
add("abc", { pattern: "(?a)^\\w+$" });         // ASCII flag
add("é", { pattern: "(?a)^\\w+$" });      // ASCII flag: e-acute not \w
add("١٢", { pattern: "(?a)^\\d+$" });// ASCII flag: arabic digits not \d
add("abc", { pattern: "(?u)^\\w+$" });
add("abc", { pattern: "(?L)^\\w+$" });         // LOCALE on str pattern -> error?
add("abc", { pattern: "(?i)ABC" });
add("ABC", { pattern: "(?-i:abc)" });
add("abc", { pattern: "a|" });
add("abc", { pattern: "|a" });
add("abc", { pattern: "(?i)(?m)(?s)abc" });
add("abc", { pattern: "^(?:a|ab)c?$" });
add("x", { pattern: "^(?i)x$" });              // inline flag not at start (3.11 error)
add("abc", { pattern: "a(?i)bc" });            // mid-pattern global flag -> error in 3.11+

// unicode \s / \b / boundary details
add("a b", { pattern: "^a\\s b$".replace(" ", "") });
add("a b", { pattern: "^a\\sb$" });       // LINE SEPARATOR
add("a​b", { pattern: "^a\\sb$" });       // ZERO WIDTH SPACE (not \s)
add("a　b", { pattern: "^a\\sb$" });       // IDEOGRAPHIC SPACE
add("ab", { pattern: "^a\\sb$" });       // vertical tab
add("ab", { pattern: "^a\\sb$" });       // FILE SEPARATOR (Python \s matches 1c-1f)
add("²", { pattern: "^\\d$" });           // superscript two: Nd? no -> No
add("²", { pattern: "^\\w$" });
add("①", { pattern: "^\\w$" });           // circled digit one
add("́", { pattern: "^\\w$" });           // combining acute alone
add("́", { pattern: "^.$" });
add("café", { pattern: "^\\w{4}$" });
add("café", { pattern: "^\\w{4}$" });
add("café", { pattern: "^\\w{4}.$" });
add("ß", { pattern: "(?i)^SS$" });        // sharp s casefolding: re does NOT
add("K", { pattern: "(?i)^k$" });         // KELVIN SIGN
add("İ", { pattern: "(?i)^i$" });         // dotted capital I

// \r handling around $
add("abc\r", { pattern: "^abc$" });
add("abc\r\n", { pattern: "^abc$" });
add("abc\n", { pattern: "^abc\\n$" });

// length bound extremes
add("abc", { minLength: 1e400 });               // Infinity in JSON? -> becomes null
add("abc", { minLength: 100000000000000000000 });
add("abc", { maxLength: 0.0 });
add("", { maxLength: 0.5 });
add("", { minLength: 0.5 });
add("ab", { minLength: 2.0000001 });
add("abc", { minLength: 3, maxLength: 3, pattern: "^abc$", type: "string" });

// counting with deeper nesting
add({ a: { b: "x" } }, { properties: { a: { properties: { b: { minLength: 5, maxLength: 0 } } } } });
add(["x", ["y"]], { items: { minLength: 5 } });
add({ a: "x", b: "y" }, { additionalProperties: { minLength: 5 } });
add(["x", "y"], { prefixItems: [{ minLength: 5 }, { minLength: 5 }] });
add(["x", "y"], { $schema: "http://json-schema.org/draft-07/schema#", items: [{ minLength: 5 }, { minLength: 5 }] });
add({ a: "x" }, { propertyNames: { minLength: 5 } });
add({ ab: "x", cd: "y" }, { propertyNames: { minLength: 5 } });
add(["x", "x"], { contains: { minLength: 5 } });
add("x", { $schema: "http://json-schema.org/draft-03/schema#", minLength: 5, maxLength: 0, pattern: "^z$", format: "email" });
add("x", { $schema: "http://json-schema.org/draft-03/schema#", type: [{ minLength: 5 }, { maxLength: 0 }] });
add("x", { dependentSchemas: { a: { minLength: 5 } } });
add("x", { minLength: 5, $comment: "hi", title: "t", description: "d", default: "z", examples: ["q"] });

const lines = [];
for (const [a, b] of vectors) {
  let out = '', code = 0;
  try {
    out = execFileSync(EXE, ['--a', a, '--b', b], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
  } catch (e) {
    out = (e.stdout || '').toString();
    code = (typeof e.status === 'number') ? e.status : 1;
  }
  lines.push(JSON.stringify({ a, b, out, exit: code }));
  const p = out.trim().split('\n');
  console.log((code ? 'EXIT' + code : (p[1] || '') + ' n=' + (p[2] || '')).padEnd(12), 'a=' + a.slice(0, 30).padEnd(32), 'b=' + b.slice(0, 110));
}
fs.appendFileSync(OUT, lines.join('\n') + '\n');
console.log('appended', lines.length);

